schema:
{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Shader Asset",
    "description": "The asset.json file for shaders.",
    "type": "object",
    "properties": {
        "asset_type": {
            "type": "string",
            "pattern": "shader"
        },
        "vert_source": {
            "description": "The source file for the GLSL vertex shader, relative to the current asset path. Defaults to vert.glsl",
            "type": "string"
        },
        "frag_source": {
            "description": "The source file for the GLSL frragment shader, relative to the current asset path. Defaults to frag.glsl",
            "type": "string"
        },
        "location_attribute_glsl_name": {
            "description": "The name of the vertex location attribute",
            "type": "string",
            "pattern": "\\w+"
        },
        "vertex_attributes": {
            "description": "The vertex attributes that this shader expects. These are to be added to a mesh.",
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "name": {
                        "description": "The name of the attribute in the mesh.",
                        "type": "string"
                    },
                    "glsl_name": {
                        "description": "The name of the attribute in GLSL",
                        "type": "string",
                        "pattern": "\\w+"
                    },
                    "type": {
                        "description": "The type of the data",
                        "type": "string",
                        "pattern": "int|float|vec2|vec3|vec4"
                    }
                },
                "required": [
                    "name",
                    "glsl_id",
                    "type"
                ]
            }
        },
        "parameters": {
            "description": "The parameters (uniforms in GLSL) for the shader.",
            "type": "array",
            "items": {
                "type": "object",
                "properties": {
                    "type": {
                        "description": "The type of the object",
                        "type": "string",
                        "pattern": "int|float|vec2|vec3|vec4|texture"
                    },
                    "glsl_name": {
                        "description": "The name of the uniorm in GLSL",
                        "type": "string",
                        "pattern": "\\w+"
                    },
                    "glsl_offset": {
                        "description": "The offset from the uniorm location fetched by glsl_name. Used for arrays, 0 by default",
                        "type": "integer",
                        "minimum": 0
                    },
                    "name": {
                        "description": "The name that will be exposed to the interface",
                        "type": "string"
                    },
                    "default": {
                        "description": "The default value for the parameter",
                        "anyOf": [
                            {
                                "type": "string"
                            },
                            {
                                "type": "array",
                                "items": {
                                    "type": "number"
                                },
                                "minItems": 2,
                                "maxItems": 4
                            },
                            {
                                "type": "number"
                            }
                        ]
                    },
                    "description": {
                        "description": "A description of the parameter",
                        "type": "string"
                    }
                },
                "required": [
                    "type",
                    "glsl_name",
                    "name",
                    "defualt"
                ]
            }
        }
    },
    "required": [
        "asset_type"
    ]
}

{
    "$id": "https://example.com/person.schema.json",
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "Person",
    "type": "object",
    "required": [
        "minzoom",
        "maxzoom",
        "tiles"
    ],
    "definitions": {
        "zoomlevel": {
            "type": "integer",
            "minimum": 0,
            "maximum": 24
        },
        "epsg": {
            "type": "string",
            "pattern": "^(epsg|EPSG):\\d{4,5}$"
        },
        "vectorLayer": {
            "type": "object",
            "required": [
                "id"
            ],
            "properties": {
                "id": {
                    "type": "string",
                    "minLength": 1
                },
                "description": {
                    "type": "string"
                },
                "minzoon": {
                    "$ref": "#/definitions/zoomlevel"
                },
                "maxzoon": {
                    "$ref": "#/definitions/zoomlevel"
                }
            }
        }
    },
    "properties": {
        "bounds": {
            "description": "Bounds MUST define an area covered by all zoom levels. The bounds are represented in WGS:84 latitude and longitude values, in the order left, bottom, right, top. Values may be integers or floating point numbers.",
            "type": "array",
            "minLength": 4,
            "maxLength": 4,
            "minimum": -180,
            "maximum": 180,
            "items": {
                "type": "number"
            }
        },
        "center": {
            "description": "The first value is the longitude, the second is latitude (both in WGS:84 values), the third value is the zoom level as an integer. Longitude and latitude MUST be within the specified bounds. The zoom level MUST be between minzoom and maxzoom.",
            "type": "array",
            "minimum": -180,
            "maximum": 180,
            "minLength": 3,
            "maxLength": 3,
            "items": {
                "type": "number"
            }
        },
        "tiles": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "json": {
            "type": "string",
            "description": "A JSON string defining a single object containing the 'vector_layers' property as an array of vector layers"
        },
        "vector_layers": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/vectorLayer"
            }
        },
        "crs": {
            "$ref": "#/definitions/epsg"
        },
        "srs": {
            "$ref": "#/definitions/epsg"
        },
        "minzoom": {
            "$ref": "#/definitions/zoomlevel"
        },
        "maxzoom": {
            "$ref": "#/definitions/zoomlevel"
        },
        "scheme": {
            "type": "string",
            "enum": [
                "tms",
                "xyz"
            ]
        }
    },
    "allOf": [
        {
            "anyOf": [
                {
                    "description": "Either 'crs' or 'srs' are allowed but not both. Both can be omitted.",
                    "not": {
                        "required": [
                            "crs",
                            "srs"
                        ]
                    }
                }
            ]
        },
        {
            "description": "Either 'json' or 'vector_layers' is required.",
            "anyOf": [
                {
                    "required": [
                        "json"
                    ]
                },
                {
                    "required": [
                        "vector_layers"
                    ]
                }
            ]
        }
    ]
}

{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "avalon-core:subset-3.0",
    "description": "A container of instances",
    "type": "object",
    "additionalProperties": true,
    "required": [
        "schema",
        "type",
        "parent",
        "name",
        "data"
    ],
    "properties": {
        "schema": {
            "description": "The schema associated with this document",
            "type": "string",
            "enum": [
                "avalon-core:subset-3.0"
            ],
            "example": "avalon-core:subset-3.0"
        },
        "type": {
            "description": "The type of document",
            "type": "string",
            "enum": [
                "subset"
            ],
            "example": "subset"
        },
        "parent": {
            "description": "Unique identifier to parent document",
            "example": "592c33475f8c1b064c4d1696"
        },
        "name": {
            "description": "Name of directory",
            "type": "string",
            "pattern": "^[a-zA-Z0-9_.]*$",
            "example": "shot01"
        },
        "data": {
            "description": "Document metadata",
            "type": "object",
            "required": [
                "families"
            ],
            "properties": {
                "families": {
                    "type": "array",
                    "items": {
                        "type": "string"
                    },
                    "description": "One or more families associated with this subset"
                }
            },
            "example": {
                "families": [
                    "avalon.camera"
                ],
                "frameStart": 1000,
                "frameEnd": 1201
            }
        }
    }
}

