                    },
                    "b2": {
                        "description": "A reference to a ending token index from the current revision",
                        "type": "number"
                    }
                }
            }
        },
        "bytes": {
            "description": "The size of revision content in bytes",
            "type": [
                "number",
                "null"
            ]
        },
        "sha1": {
            "description": "A sha1 hash of the revision content",
